#!/usr/bin/env python3
"""Pack canonical target-generated bytes; --check never rewrites the asset."""
import argparse
import hashlib
import json
from pathlib import Path
import re
import zlib

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[1]
META = HERE / 'jewel_matcap.json'
OUT = ROOT / 'cube/swiss/source/gui/ui_jewel_matcap.inc'


def payload_text(data: bytes) -> str:
    packed = zlib.compress(data, 9)
    return ('/* Generated by buildtools/ui/generate_jewel_matcap.py; see jewel_matcap.json. */\n'
            f'#define JEWEL_MATCAP_BYTES {len(data)}u\n'
            f'#define JEWEL_MATCAP_CRC32 0x{zlib.crc32(data):08x}u\n'
            'static const u8 jewelMatcapPacked[] = {\n' + ''.join(
                '\t' + ', '.join(f'0x{x:02x}' for x in packed[i:i+16]) + ',\n'
                for i in range(0, len(packed), 16)) + '};\n')


def validate(data: bytes, meta: dict) -> None:
    if len(data) != meta['bytes'] or hashlib.sha256(data).hexdigest() != meta['sha256']:
        raise ValueError('Target texture differs from the canonical resource; review an intentional update')
    if f'{zlib.crc32(data):08x}' != meta['crc32']:
        raise ValueError('Texture checksum differs')


def main() -> None:
    args = argparse.ArgumentParser(description=__doc__)
    args.add_argument('--capture', type=Path, help='UART log from jewel_matcap_export.c')
    args.add_argument('--check', action='store_true', help='verify without rewriting')
    opts = args.parse_args()
    meta = json.loads(META.read_text())
    if opts.capture:
        raw = bytearray()
        for offset, hex_text in re.findall(r'matcap (\d+) ([0-9a-f]+)', opts.capture.read_text()):
            if int(offset) != len(raw) or len(raw) + len(hex_text)//2 > meta['bytes']:
                raise ValueError('Incomplete, duplicated or oversized target capture')
            raw.extend(bytes.fromhex(hex_text))
        data = bytes(raw)
    else:
        packed = bytes(int(x,16) for x in re.findall(r'0x([0-9a-f]{2})(?=,|\s)', OUT.read_text()))
        decoder = zlib.decompressobj()
        data = decoder.decompress(packed, meta['bytes']+1)
        if not decoder.eof or decoder.unused_data or decoder.unconsumed_tail:
            raise ValueError('Compressed resource has trailing or incomplete data')
    validate(data, meta)
    expected = payload_text(data)
    if opts.check:
        if OUT.read_text() != expected:
            raise ValueError('Generated include differs; regenerate it deliberately')
    elif opts.capture:
        OUT.write_text(expected)
    print(f"matcap: {len(data)} exact bytes, {len(zlib.compress(data,9))} compressed bytes")


if __name__ == '__main__':
    main()
